void paintLines(QPlainTextEdit& view,const NativeModuleBreakpoints& points,const QByteArray& code,int current=0) {
    QList<QTextEdit::ExtraSelection> selections;
    const auto add=[&](int line,const QColor& color) {const auto block=view.document()->findBlockByNumber(line-1);if(!block.isValid()) return;QTextEdit::ExtraSelection selection;selection.cursor=QTextCursor(block);selection.format.setBackground(color);selection.format.setForeground(Qt::black);selection.format.setProperty(QTextFormat::FullWidthSelection,true);selections.append(selection);};
    for(const int line:points.lines.value(code)) add(line,QColor(255,180,180));if(current>0) add(current,QColor(255,239,145));view.setExtraSelections(selections);
}
bool toggleBreakpoint(NativeModuleBreakpoints& points,const QByteArray& code,int line) {
    std::string procedure;for(const auto& item:linaccess::analyzeVba(code.toStdString()).procedures) if(item.line<=line) procedure=item.name;else break;
    if(procedure.empty()) return false;const auto executable=linaccess::vbaDebugExecutableLines(code.toStdString(),procedure);if(std::find(executable.begin(),executable.end(),line)==executable.end()) return false;
    auto& lines=points.lines[code];if(lines.contains(line)) lines.remove(line);else lines.insert(line);if(lines.isEmpty()) points.lines.remove(code);return true;
}
QString typeLabel(const linaccess::VbaDebugVariable& value) {return QString::fromStdString(value.valueType);}
class EditorCloseGuard final:public QObject {
public:std::function<void()> stop;bool closing{};
    bool eventFilter(QObject*,QEvent* event) override {if(event->type()==QEvent::Close || (event->type()==QEvent::KeyPress && static_cast<QKeyEvent*>(event)->key()==Qt::Key_Escape)) {closing=true;if(stop) stop();event->ignore();return true;}return false;}
};
