void installNativeModuleBreakpoints(QDialog& editor,QPlainTextEdit& source,const std::shared_ptr<NativeModuleBreakpoints>& points) {
    auto* status=new QLabel(&editor);status->setObjectName("native-module-breakpoint-status");status->setTextFormat(Qt::PlainText);status->setText("F9 setzt oder entfernt einen Haltepunkt; Strg+Pause unterbricht laufenden Code.");editor.layout()->addWidget(status);
    const QPointer<QPlainTextEdit> text=&source;const QPointer<QLabel> message=status;auto last=std::make_shared<QByteArray>(source.toPlainText().toUtf8());
    auto* shortcut=new QShortcut(QKeySequence(Qt::Key_F9),&source);shortcut->setContext(Qt::WidgetShortcut);QObject::connect(shortcut,&QShortcut::activated,&editor,[text,message,points] {if(!text || !message) return;const auto code=text->toPlainText().toUtf8();const int line=text->textCursor().blockNumber()+1;try {const bool changed=toggleBreakpoint(*points,code,line);message->setText(changed ? QString("Haltepunkt in Zeile %1 %2.").arg(line).arg(points->lines.value(code).contains(line) ? "gesetzt" : "entfernt") : "Diese Zeile enthält keine unterstützte ausführbare Anweisung.");paintLines(*text,*points,code);}catch(const std::exception& error) {message->setText(QString::fromUtf8(error.what()));}});
    QObject::connect(&source,&QPlainTextEdit::textChanged,&editor,[text,message,points,last] {if(!text) return;const bool removed=points->lines.remove(*last)>0;*last=text->toPlainText().toUtf8();paintLines(*text,*points,*last);if(removed && message) message->setText("Quelltext geändert; Haltepunkte für die neue Revision erneut setzen.");});
}
